using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace Aurora {
public sealed class UpgradeItem {
    public string Id,Name,Current,Available,Source;
    public override string ToString(){return Name+" • "+Current+" → "+Available+" • "+Source;}
}
public static class UpgradeInventory {
    public static bool QuerySucceeded(int code){return code==0||unchecked((uint)code)==0x8A15002B;}
    public static List<UpgradeItem> Winget(string output){var items=new List<UpgradeItem>();foreach(string row in (output??"").Split('\n')){string[] parts=Regex.Split(row.Trim(),@"\s{2,}");if(parts.Length<4)continue;string id=parts[1];if(!Runner.ValidId(id)||!id.Contains("."))continue;items.Add(new UpgradeItem{Name=parts[0],Id=id,Current=parts[2],Available=parts[3],Source=parts.Length>4?parts[4]:"winget"});}return items.GroupBy(x=>x.Id,StringComparer.OrdinalIgnoreCase).Select(x=>x.First()).ToList();}
    public static List<UpgradeItem> Chocolatey(string output){var items=new List<UpgradeItem>();foreach(string row in (output??"").Split('\n')){string[] parts=row.Trim().Split('|');if(parts.Length<3||!Runner.ValidId(parts[0]))continue;items.Add(new UpgradeItem{Name=parts[0],Id=parts[0],Current=parts[1],Available=parts[2],Source="Chocolatey"});}return items;}
    public static bool ValidSource(string name,string url){Uri uri;return Regex.IsMatch(name??"","^[A-Za-z0-9][A-Za-z0-9_-]{1,39}$")&&Uri.TryCreate(url,UriKind.Absolute,out uri)&&uri.Scheme==Uri.UriSchemeHttps&&uri.UserInfo==""&&uri.Host.Length>0;}
}
